import json,pathlib,subprocess,statistics,hashlib,html
out=pathlib.Path(__file__).parent/'final'
records=json.loads((out/'recording-metrics.json').read_text());stats=[]
for r in records:
 name=r['name'];target=out/f'{name}.mp4'
 subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss',str(max(0,r['readyOffset']-.25)),'-i',r['raw'],'-an','-vf','fps=25,setpts=PTS-STARTPTS','-frames:v',str(r['duration']*25),'-c:v','libx264','-preset','fast','-crf','18','-pix_fmt','yuv420p','-movflags','+faststart',str(target)],check=True)
 probe=json.loads(subprocess.check_output(['ffprobe','-v','error','-show_entries','stream=codec_name,width,height,nb_frames,r_frame_rate:format=duration','-of','json',str(target)]))
 frames=r['frames'];frames=[f for f in frames if f['t']<=frames[0]['t']+r['duration']*1000]
 cpu=[f['cpuFrameMs'] for f in frames];gpu=[f['gpuFrameMs'] for f in frames if f['gpuFrameMs'] is not None]
 windows=[]
 for start in range(int((frames[-1]['t']-frames[0]['t'])//1000)):
  windows.append(sum(frames[0]['t']+start*1000<=f['t']<frames[0]['t']+(start+1)*1000 for f in frames))
 q=lambda xs,p:sorted(xs)[min(len(xs)-1,int((len(xs)-1)*p))]
 stat={'mode':name,'videoTrimStartSeconds':max(0,r['readyOffset']-.25),'renderer':r['metrics']['renderer'],'video':probe,'renderFpsActiveMean':round((len(frames)-1)*1000/(frames[-1]['t']-frames[0]['t']),2),'renderFpsOneSecondMin':min(windows),'renderFpsOneSecondMedian':statistics.median(windows),'renderFpsOneSecondMax':max(windows),'cpuSubmissionMedianMs':round(statistics.median(cpu),2),'cpuSubmissionP95Ms':round(q(cpu,.95),2),'gpuQueryLatestMedianMs':round(statistics.median(gpu),2),'gpuQueryLatestP95Ms':round(q(gpu,.95),2),'DPR':sorted(set(f['dpr'] for f in frames)),'drawCallsRange':[min(f['drawCalls'] for f in frames),max(f['drawCalls'] for f in frames)],'trianglesRange':[min(f['triangles'] for f in frames),max(f['triangles'] for f in frames)],'finalFilaments':r['metrics']['filaments'],'errors':r['errors'],'activeMeasurementSeconds':round((frames[-1]['t']-frames[0]['t'])/1000,2)}
 stats.append(stat)
 subprocess.run(['ffmpeg','-hide_banner','-loglevel','error','-y','-ss','8','-i',str(target),'-frames:v','1',f'/tmp/progresskit-three-{name}-video-check.png'],check=True)
(out/'performance.json').write_text(json.dumps(stats,indent=2))
figures=[('idle','Idle po ponad 6 sekundach'),('activation','Aktywacja Core'),('materialization','Materializacja geometrii'),('hover','Raycast projektu Mail'),('core-closeup','Zbliżenie Core — wycinek natywnego renderu'),('mobile','Mobile — jeden kryształ')]
cards=''.join(f'<figure><a href="{n}.png"><img src="{n}.png" alt="{label}" loading="lazy"></a><figcaption>{label}</figcaption></figure>' for n,label in figures)
rows=''.join(f'<tr><td>{s["mode"]}</td><td>{s["renderFpsActiveMean"]}</td><td>{s["renderFpsOneSecondMin"]}–{s["renderFpsOneSecondMax"]}</td><td>{s["cpuSubmissionMedianMs"]} ms</td><td>{s["gpuQueryLatestMedianMs"]} ms</td><td>{s["drawCallsRange"]}</td><td>{s["trianglesRange"]}</td></tr>' for s in stats)
(out/'index.html').write_text('''<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ProgressKit — showroom Three.js / owner review</title><style>body{margin:0;background:#080d12;color:#dce6ec;font:16px/1.6 system-ui}main{max-width:1300px;margin:auto;padding:32px}h1{font-size:30px}a{color:#a8d9f4}video,img{max-width:100%;height:auto;background:#03070a}video{max-height:760px}figure{margin:0}figcaption{padding:10px 0 24px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}.videos{display:grid;grid-template-columns:2fr 1fr;gap:24px}table{border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid #34424c;padding:10px}.scroll{overflow:auto}@media(max-width:720px){.grid,.videos{display:block}}</style><main><h1>Showroom Three.js / WebGL2</h1><p>ownerVisualApproval: <strong>OPEN</strong>. Lokalna wersja do oceny wizualnej, bez commita i pushu.</p><p><a href="http://127.0.0.1:8191/#showroom-track">Otwórz interaktywny showroom</a> · <a href="performance.json">Pełne pomiary</a> · <a href="qa.json">36 testów przeglądarkowych</a></p><div class="videos"><figure><video controls preload="metadata" poster="idle.png" src="desktop.mp4"></video><figcaption>Desktop · 18 s · co najmniej 6 s idle, aktywacja, materializacja, raycast i reakcja na kursor.</figcaption></figure><figure><video controls preload="metadata" poster="mobile.png" src="mobile.mp4"></video><figcaption>Mobile · 15 s · emulacja 390 × 844 na tym samym GPU; nie test fizycznego telefonu.</figcaption></figure></div><p>Intel Core i7-8650U / Intel UHD 620, Chrome/ANGLE OpenGL. Filmy zakodowane w 25 FPS; poniżej rzeczywista częstotliwość renderowania sceny. Mobile po otwarciu treści zatrzymuje RAF.</p><div class="scroll"><table><tr><th>Tryb</th><th>FPS średnio podczas animacji</th><th>Okna 1 s</th><th>CPU mediana</th><th>GPU mediana</th><th>Draw calls</th><th>Trójkąty</th></tr>'''+rows+'''</table></div><p>CPU oznacza czas obsługi i zlecania renderu w JS, bez oczekiwania na GPU. GPU: ostatnie dostępne zapytania EXT_disjoint_timer_query_webgl2. Materiał ma adaptacyjny DPR; niższa rozdzielczość jest widoczna w detalach. Hum 54 Hz jest domyślnie wyłączony i nie znajduje się na nagraniach. Włącza go wyłącznie przycisk „Włącz hum”.</p><div class="grid">'''+cards+'''</div><p>47 testów jednostkowych/regresyjnych i 36 przeglądarkowych: PASS. Ocena estetyki pozostaje po stronie ownera.</p></main></html>''')
print(json.dumps(stats,indent=2))
